{"command":"$live = "C:\Users\kingd\.grok\sessions\F%3A%5CGitHub%5Cvice-sharp\019fd0df-383d-7fc0-9f0a-69785afd78ed"
$arch = "F:\GitHub\vice-sharp\docs\grok\2026-08-11-vic20-exact-session"

# 1) Turn timeline from events (small, high value)
$turnOut = Join-Path $arch "timeline-turns.jsonl"
Get-Content (Join-Path $live "events.jsonl") | ForEach-Object {
  try {
    $o = $_ | ConvertFrom-Json
    if ($o.type -in @('turn_started','turn_ended','interjected','goal_auto_paused')) { $_ }
  } catch {}
} | Set-Content -Path $turnOut -Encoding utf8
Write-Host "turns written: $((Get-Content $turnOut | Measure-Object -Line).Lines) size=$((Get-Item $turnOut).Length)"

# 2) Compact timed chat from updates: collapse message chunks + keep turn boundaries
# updates timestamps look like unix seconds? 1785915723 -> date
$epoch = [DateTimeOffset]::FromUnixTimeSeconds(1785915723)
Write-Host "sample epoch decode: $epoch UTC"

$upd = Join-Path $live "updates.jsonl"
# Stream and collapse - may take a bit on 245MB
$outPath = Join-Path $arch "chat_history.timestamped.jsonl"
$sw = [System.IO.StreamWriter]::new($outPath, $false, [System.Text.UTF8Encoding]::new($false))
$reader = [System.IO.StreamReader]::new($upd)
$curType = $null
$curParts = [System.Collections.Generic.List[string]]::new()
$curTs = $null
$curEndTs = $null
$nOut = 0
$nIn = 0
$flush = {
  if ($null -ne $curType -and $curParts.Count -gt 0) {
    $text = [string]::Concat($curParts)
    # cap extremely long blobs in archive-friendly form? keep full text for audit honesty
    $obj = [ordered]@{
      ts_start = $curTs
      ts_end = $curEndTs
      type = $curType
      content = $text
    }
    $sw.WriteLine(($obj | ConvertTo-Json -Compress -Depth 5))
    $script:nOut++
    $curParts.Clear()
  }
}

while ($null -ne ($line = $reader.ReadLine())) {
  $nIn++
  if (($nIn % 200000) -eq 0) { Write-Host "processed $nIn lines, out=$nOut" }
  try { $o = $line | ConvertFrom-Json } catch { continue }
  $ts = $o.timestamp
  $u = $o.params.update
  if ($null -eq $u) { continue }
  $su = $u.sessionUpdate

  switch ($su) {
    'user_message_chunk' {
      $piece = $u.content
      if ($null -eq $piece) { $piece = $u.text }
      if ($null -eq $piece -and $u.content -is [array]) { $piece = ($u.content | ForEach-Object { $_.text }) -join '' }
      # structure varies; try common shapes
      if ($null -eq $piece) {
        if ($u.PSObject.Properties.Name -contains 'content') {
          $c = $u.content
          if ($c -is [string]) { $piece = $c }
          elseif ($c.text) { $piece = $c.text }
        }
      }
      if ($curType -ne 'user') { & $flush; $curType = 'user'; $curTs = $ts }
      if ($null -ne $piece) { $curParts.Add([string]$piece) }
      $curEndTs = $ts
    }
    'agent_message_chunk' {
      $piece = $null
      if ($u.content -is [string]) { $piece = $u.content }
      elseif ($u.text) { $piece = $u.text }
      elseif ($u.content.text) { $piece = $u.content.text }
      if ($curType -ne 'assistant') { & $flush; $curType = 'assistant'; $curTs = $ts }
      if ($null -ne $piece) { $curParts.Add([string]$piece) }
      $curEndTs = $ts
    }
    'agent_thought_chunk' {
      $piece = $null
      if ($u.content -is [string]) { $piece = $u.content }
      elseif ($u.text) { $piece = $u.text }
      elseif ($u.content.text) { $piece = $u.content.text }
      if ($curType -ne 'reasoning') { & $flush; $curType = 'reasoning'; $curTs = $ts }
      if ($null -ne $piece) { $curParts.Add([string]$piece) }
      $curEndTs = $ts
    }
    'tool_call' {
      & $flush
      $curType = $null
      $obj = [ordered]@{
        ts = $ts
        type = 'tool_call'
        toolCallId = $u.toolCallId
        title = $u.title
        kind = $u.kind
        status = $u.status
        raw = $u
      }
      # avoid huge raw - slim fields
      $slim = [ordered]@{
        ts = $ts
        type = 'tool_call'
        toolCallId = $u.toolCallId
        title = $u.title
        kind = $u.kind
        status = $u.status
      }
      if ($u.name) { $slim.name = $u.name }
      if ($u.toolName) { $slim.toolName = $u.toolName }
      $sw.WriteLine(($slim | ConvertTo-Json -Compress -Depth 8))
      $nOut++
    }
    'tool_call_update' {
      # only emit completed/failed to keep size down
      $st = $u.status
      $statusName = if ($st -is [string]) { $st } elseif ($st.status) { $st.status } else { $null }
      if ($statusName -in @('completed','failed','error','cancelled')) {
        $slim = [ordered]@{
          ts = $ts
          type = 'tool_call_update'
          toolCallId = $u.toolCallId
          status = $statusName
        }
        $sw.WriteLine(($slim | ConvertTo-Json -Compress -Depth 5))
        $nOut++
      }
    }
    default { }
  }
}
& $flush
$reader.Close(); $sw.Close()
Write-Host "DONE in=$nIn out=$nOut size=$((Get-Item $outPath).Length) path=$outPath"

# Inspect first few timestamped records
Get-Content $outPath -TotalCount 8 | ForEach-Object { $_.Substring(0,[Math]::Min(200,$_.Length)) }
Write-Host "---"
# Sample structure of user_message_chunk from updates
$found = 0
$r2 = [System.IO.StreamReader]::new($upd)
while ($null -ne ($line = $r2.ReadLine()) -and $found -lt 2) {
  if ($line -match 'user_message_chunk') {
    Write-Host $line.Substring(0, [Math]::Min(600, $line.Length))
    $found++
  }
}
$r2.Close()
","description":"Build timestamped turn timeline and chat export"}

